import{_ as t,o,c as d,a5 as i}from"./chunks/framework.DSg0KOwT.js";const w=JSON.parse('{"title":"Finding widget shell","description":"","frontmatter":{},"headers":[],"relativePath":"contributor-guide/architecture/widget-rendering/finding-widget-shell.md","filePath":"contributor-guide/architecture/widget-rendering/finding-widget-shell.md"}'),n={name:"contributor-guide/architecture/widget-rendering/finding-widget-shell.md"};function a(s,e,c,r,l,h){return o(),d("div",null,[...e[0]||(e[0]=[i('<h1 id="finding-widget-shell" tabindex="-1">Finding widget shell <a class="header-anchor" href="#finding-widget-shell" aria-label="Permalink to &quot;Finding widget shell&quot;">​</a></h1><p>How a finding widget is built, and the steps to add one.</p><p>Every finding widget is made by one function, <code>defineFindingWidget</code> (<code>src/view/finding-widget.tsx</code>). It takes a per-widget row model and a <code>Row</code> component. The model decides what the widget shows. The <code>Row</code> draws it. The shell owns everything else.</p><h2 id="what-each-part-owns" tabindex="-1">What each part owns <a class="header-anchor" href="#what-each-part-owns" aria-label="Permalink to &quot;What each part owns&quot;">​</a></h2><ul><li>The row model, <code>&lt;Widget&gt;.rows.ts</code>, owns the facts. A row decides, as data, whether its finding is stated by the line above an evidence panel and what the density shows (for example a <code>showStatus</code> flag). The <code>rows</code> function is pure.</li><li>The <code>Row</code> component, <code>&lt;Widget&gt;.tsx</code>, renders only what its row says. It makes no decision of its own and reads no store, context or density.</li><li>The shell owns the <code>WidgetCard</code>, the title (the finding&#39;s core name from <code>findingName</code>, unless the model gives a plural <code>title</code>), the ALL-CAPS tag, the sort toggle, the paging, the route index and the row anchors. See <a href="./list-sort-mode.html">List sort mode</a>, <a href="./row-expand-contract.html">Row/expand contract</a> and <a href="./investigation-routing.html">Investigation routing</a>.</li><li>Mounting follows the rows. The widget renders when <code>rows(...).length &gt; 0</code> and renders nothing otherwise. The same <code>rows</code> function feeds the evidence panel, <code>computeActiveWidgets</code> and the Clean checks list, so the card, its evidence control and its panel exist together or not at all. A model sets <code>alwaysMounted</code> only for a run-wide reference tile.</li></ul><h2 id="row-model" tabindex="-1">Row model <a class="header-anchor" href="#row-model" aria-label="Permalink to &quot;Row model&quot;">​</a></h2><p><code>FindingWidgetModel</code> (<code>src/view/finding-widget.tsx</code>) has these fields. Only <code>type</code>, <code>rows</code> and <code>stageOf</code> are required.</p><ul><li><code>type</code>: the finding type.</li><li><code>rows</code>: a <code>RowsOf</code> function. It takes <code>PanelInput</code> and returns the rows in base order. <code>PanelInput</code> has the findings, the stated ids, the density, the <code>appModel</code> and the run&#39;s catalog. Every row lists the findings it stands for in <code>findings</code>.</li><li><code>stageOf</code>: the stage number of a row, for the stage sort. It returns null for a row with no stage.</li><li><code>summary</code>: the collapsed card&#39;s lead value and context.</li><li><code>title</code>, <code>tagClassName</code>, <code>tagDocAnchor</code>: a plural card title, tag colour classes, and a doc anchor taken from the rows.</li><li><code>findings</code>: the findings the widget is for, when it is not the type&#39;s findings in the catalog (Config Audit reads <code>configFindings</code>).</li><li><code>sections</code>, <code>jumpLabel</code>, <code>rowElement</code>, <code>rowClassName</code>, <code>separated</code>, <code>listClassName</code>: sections with their own paging, the jump control, and the row layout.</li></ul><p>The view passed beside the model has a required <code>Row</code> and the optional <code>Lead</code>, <code>Summary</code>, <code>Frame</code> and <code>Status</code> slots.</p><h2 id="adding-a-finding-widget" tabindex="-1">Adding a finding widget <a class="header-anchor" href="#adding-a-finding-widget" aria-label="Permalink to &quot;Adding a finding widget&quot;">​</a></h2><ol><li>Add the detector side first: the folder <code>packages/core/src/detectors/&lt;type&gt;/</code> with its <code>detect.ts</code> and its entry in <code>detectors/index.ts</code>, as listed in <a href="./../detector-contract.html">Detector contract</a>. The compiler reports a missing piece.</li><li>Add the presentation row in core, in the folder&#39;s <code>presentation.ts</code> (<code>FINDING_PRESENTATION</code> assembles it), its entry in <code>detectors/presentations.ts</code> and its path on <code>ALLOWED_EXPORT_CORE_MODULES</code> in <code>scripts/export-analysis-guard.mjs</code>. It holds the finding&#39;s name, tag, family, one-sentence pitch and summary. The card title comes from the name.</li><li>Add <code>src/view/widgets/&lt;Widget&gt;.rows.ts</code>. It exports the row type (extending <code>WidgetRow&lt;&#39;type&#39;&gt;</code>), the <code>rows</code> function and the model. Put every decision in the row: whether it is stated (<code>isStated(finding, stated)</code>), what the density shows, which extension text it has. Return no row for a finding the widget has nothing to show for. <code>RetryWaste.rows.ts</code> is the smallest example.</li><li>Add <code>src/view/widgets/&lt;Widget&gt;.tsx</code>. It has a <code>Row</code> component and <code>export const &lt;Widget&gt; = defineFindingWidget(&lt;widget&gt;Model, { Row })</code>. <code>RetryWaste.tsx</code> is the smallest example.</li><li>In <code>src/view/detector-registry.tsx</code>, add the lazy import for the widget and the <code>REGISTRY</code> entry with its <code>component</code>, <code>widgetId</code>, <code>routeable</code> and <code>model:</code>. The entry has no <code>content</code> and no hand-written <code>region</code>; the region comes from the presentation row.</li><li>Test the <code>rows</code> function in the widget&#39;s own test file: the rows for a finding that is stated and one that is not, at Basic and at Advanced. Do not test title, tag, sort, paging, route index or anchors there. <code>tests/view/finding-widget.test.tsx</code> tests them once for every widget.</li><li>Add the tag to <code>AGENTS.md</code>&#39;s tag list when it is new, and add the <code>.changeset/*.md</code>.</li></ol><h2 id="rules" tabindex="-1">Rules <a class="header-anchor" href="#rules" aria-label="Permalink to &quot;Rules&quot;">​</a></h2><ul><li>A row decides the stated and density facts as data. The <code>Row</code> renders only that.</li><li>The shell owns the card, the title, the tag, the sort, the paging, the route index and the anchors. A widget file does not use <code>WidgetCard</code>, <code>TagBadge</code>, <code>RowPagination</code>, <code>SortModeToggle</code> or <code>AdvancedOnly</code>, and does not call the sort, paging, anchor, route, density or inline-evidence hooks (<code>finding-widget-uses-the-shell</code>).</li><li><code>.rows.ts</code> files are pure. They may not import React, the store, a context or a hook module, call a hook, or read a global, the clock or randomness (<code>rows-are-pure</code>, <code>rows-are-pure-inline</code>). A value a row needs goes into <code>PanelInput</code>.</li><li>A table cell never compares numbers, and a chip comes from a finding (<code>no-numeric-severity-in-cell</code>). StageTable shows a chip on a Retried or Spill cell only when the <code>retryWaste</code> or <code>spill</code> detector flagged the stage, in that finding&#39;s impact band. Fetch Wait and I/O Ratio show raw numbers.</li><li>Hiding after render is banned, including <code>empty:hidden</code>. An element with nothing to show is not a row.</li></ul><p>See <a href="./../../testing.html#structure-rules">Structure rules</a> for the rules and <a href="./../widget-rendering.html#evidence-placement">Evidence placement</a> for where a finding&#39;s evidence shows.</p>',14)])])}const f=t(n,[["render",a]]);export{w as __pageData,f as default};
